test('actual React hook clears old resource data on failed path changes and ignores late reads',async()=>{
 const source=fs.mkdtempSync(path.join(rootPath,'src','audit-hook-'));fs.writeFileSync(path.join(source,'index.tsx'),`import React from 'react';import {useApi} from '../hooks';export default function Probe({path}:{path:string}){const live=useApi<any>(path,null,0);return <div data-loading={live.loading}>{live.data?.name||'empty'} | {live.error}</div>}`);
 let resolveOld;const page=await mounted(path.relative(path.join(rootPath,'src'),path.join(source,'index.tsx')),{path:'/a'},p=>p==='/a'?Promise.resolve({name:'Guest A'}):p==='/slow'?new Promise(r=>resolveOld=r):Promise.reject(Error('Guest B unavailable')));
 try{assert.ok(page.container.textContent.includes('Guest A'));await page.render({path:'/slow'});assert.ok(page.container.textContent.startsWith('empty'));await page.render({path:'/b'});assert.ok(page.container.textContent.includes('empty | Guest B unavailable'));await act(async()=>resolveOld({name:'late old guest'}));assert.ok(page.container.textContent.includes('empty | Guest B unavailable'));assert.ok(!page.container.textContent.includes('late old guest'));}finally{await page.close();fs.rmSync(source,{recursive:true,force:true});}
});

