test('Reports deduplicate shared archive data, respect period and node, and preserve missing readings',async()=>{
 const now=Date.now(),GiB=1024**3,points=[{id:'n1/shared',node:'n1',storage:'nas',volid:'nas:backup/one',shared:true,type:'qemu',vmid:101,created:new Date(now-3600000).toISOString(),size:2*GiB},{id:'n2/shared',node:'n2',storage:'nas',volid:'nas:backup/one',shared:true,type:'qemu',vmid:101,created:new Date(now-3600000).toISOString(),size:2*GiB},{id:'n1/missing',node:'n1',storage:'local',created:new Date(now-2000000).toISOString(),size:null},{id:'old',node:'n1',created:new Date(now-10*86400000).toISOString(),size:20*GiB}];
 const page=await mounted('pages/BackupReports.tsx',{hours:'24',setHours(){}},async p=>p==='/restore'?{points,errors:[]}:reportApi(p));try{
  const card=[...page.container.querySelectorAll('.report-stats>.card')].find(c=>c.textContent.includes('Known Archive Data'));assert.ok(card.textContent.includes('2.0 GiB'));assert.ok(card.textContent.includes('partial'));
  const node=page.container.querySelector('[aria-label="Report node"]');await act(async()=>{node.value='n2';node.dispatchEvent(new page.dom.window.Event('change',{bubbles:true}));});assert.ok(card.textContent.includes('2.0 GiB'));assert.equal(page.container.querySelectorAll('.backup-report-table tbody tr').length,1);
  await page.click(button(page.container,'Report Coverage'));assert.ok(page.container.querySelector('.modal').textContent.includes('Returned Proxmox vzdump tasks'));
 }finally{await page.close()}
});
