test('Report builder exports storage readings and coverage without inventing scheduled deliveries',async()=>{
 const blobs=[],original=URL.createObjectURL,revoke=URL.revokeObjectURL;URL.createObjectURL=value=>{blobs.push(value);return 'blob:reports'};URL.revokeObjectURL=()=>{};
 const calls=[],GiB=1024**3;const page=await mounted('pages/BackupReports.tsx',{hours:'168',setHours(){}},async(p,init)=>{calls.push({p,init});return p==='/proxmox/storage'?{resources:[{id:'n1/local',name:'local',node:'n1',type:'dir',content:'backup',shared:false,status:'online',capacity:10*GiB,used:3*GiB}],errors:[]}:p==='/restore'?{points:[],errors:[]}:reportApi(p)});page.dom.window.HTMLAnchorElement.prototype.click=function(){};try{
  await page.click([...page.container.querySelectorAll('.report-builder-list>button')].find(b=>b.textContent.includes('Storage Report')));assert.equal(page.container.querySelector('[aria-label="Report contents"]').value,'storage');const form=page.container.querySelector('.report-build-form');await act(async()=>form.dispatchEvent(new page.dom.window.Event('submit',{bubbles:true,cancelable:true})));
  const result=JSON.parse(await blobs[0].text());assert.equal(result.kind,'storage');assert.equal(result.destinations.length,1);assert.equal(result.destinations[0].used,3*GiB);assert.ok(result.archiveCoverage.scope.includes('node and period'));assert.equal(result.tasks,undefined);assert.ok(!calls.some(call=>['POST','PUT','DELETE'].includes(call.init?.method)));
 }finally{await page.close();URL.createObjectURL=original;URL.revokeObjectURL=revoke}
});
